<?php
$uid = (int)$u['id'];
handle('dep_add', function () use ($uid) { $d = Pay::findUser((string)$_POST['who'], $uid); if (val('SELECT 1 FROM dependents WHERE dependent_id=? AND guardian_id=?', [$d['id'], $uid])) throw new AppError('Already your dependent.'); $p = cents($_POST['per'] ?? ''); $dl = cents($_POST['daily'] ?? ''); if ($p <= 0 || $dl < $p) throw new AppError('Daily limit must be at least the per-payment limit.'); q('INSERT INTO dependents (guardian_id,dependent_id,per_txn_limit,daily_limit) VALUES (?,?,?,?)', [$uid, $d['id'], dec($p), dec($dl)]); notify((int)$d['id'], 'security', 'Guardian controls added', $u['name'] . ' set spending limits on your wallet.'); return 'Dependent linked.'; });
handle('dep_update', function () use ($uid) { $r = row('SELECT * FROM dependents WHERE id=? AND guardian_id=?', [(int)$_POST['id'], $uid]); if (!$r) throw new AppError('Not found.'); $p = cents($_POST['per'] ?? ''); $dl = cents($_POST['daily'] ?? ''); if ($p <= 0 || $dl < $p) throw new AppError('Daily limit must be at least the per-payment limit.'); q('UPDATE dependents SET per_txn_limit=?, daily_limit=?, status=? WHERE id=?', [dec($p), dec($dl), ($_POST['status'] ?? '') === 'paused' ? 'paused' : 'active', $r['id']]); return 'Controls updated.'; });
handle('res_add', function () use ($uid) { $r = row('SELECT * FROM dependents WHERE id=? AND guardian_id=?', [(int)$_POST['id'], $uid]); if (!$r) throw new AppError('Not found.'); $v = trim((string)$_POST['value']); if ($v === '') throw new AppError('Enter a value.'); q('INSERT INTO dependent_restrictions (dependent_row_id,restriction_type,value) VALUES (?,?,?)', [$r['id'], $_POST['rtype'] === 'merchant' ? 'merchant' : 'category', mb_substr($v, 0, 80)]); return 'Restriction added.'; });
handle('res_del', function () use ($uid) { q('DELETE r FROM dependent_restrictions r JOIN dependents d ON d.id=r.dependent_row_id WHERE r.id=? AND d.guardian_id=?', [(int)$_POST['id'], $uid]); return 'Removed.'; });
handle('pol_set', function () use ($uid) { $w = row('SELECT w.* FROM wallets w WHERE w.id=? AND w.currency="BDT" AND (w.user_id=? OR w.user_id IN (SELECT dependent_id FROM dependents WHERE guardian_id=?))', [(int)$_POST['wallet'], $uid, $uid]); if (!$w) throw new AppError('You cannot set a policy on that wallet.'); $min = cents($_POST['min'] ?? ''); $need = (int)$_POST['need']; $ids = []; foreach (preg_split('/[\s,;]+/', trim((string)$_POST['approvers'])) as $e) if ($e !== '') $ids[] = (int)Pay::findUser($e, 0)['id'];
  $ids = array_values(array_unique($ids)); if ($min <= 0 || $need < 1 || $need > count($ids)) throw new AppError('Set a threshold, and a number of approvals between 1 and the number of approvers.'); tx(function () use ($w, $min, $need, $ids, $uid) { q('DELETE FROM approval_policies WHERE wallet_id=?', [$w['id']]); q('INSERT INTO approval_policies (wallet_id,min_amount,required_approvals,created_by) VALUES (?,?,?,?)', [$w['id'], dec($min), $need, $uid]); $pid = (int)db()->lastInsertId(); foreach ($ids as $i) q('INSERT INTO approval_policy_approvers (policy_id,user_id) VALUES (?,?)', [$pid, $i]); }); return 'Approval policy saved.'; });
handle('pol_del', function () use ($uid) { q('DELETE FROM approval_policies WHERE wallet_id=? AND created_by=?', [(int)$_POST['wallet'], $uid]); return 'Policy removed.'; });
handle('vote', function () use ($uid) { $r = Approvals::vote($uid, (int)$_POST['id'], $_POST['decision'] === 'reject' ? 'reject' : 'approve'); return 'Vote recorded: ' . $r; });
echo page_head('Family & guardians', 'Dependent wallets with spending limits, restrictions and multi-approver authorization.');
$deps = rows('SELECT d.*, u.name, u.email FROM dependents d JOIN users u ON u.id=d.dependent_id WHERE d.guardian_id=? ORDER BY d.id', [$uid]); $dh = '';
foreach ($deps as $d) { $rs = rows('SELECT * FROM dependent_restrictions WHERE dependent_row_id=?', [$d['id']]); $rh = ''; foreach ($rs as $r) $rh .= '<span class="chip">' . e($r['restriction_type']) . ': ' . e($r['value']) . form_start('res_del', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$r['id'] . '"><button class="btn ghost sm" style="min-height:0;padding:0 4px" aria-label="Remove restriction">x</button></form></span> ';
  $dh .= card($d['name'], '<div class="hint">' . e(mask_email($d['email'])) . ' &middot; ' . badge($d['status']) . '</div>' . form_start('dep_update') . '<input type="hidden" name="id" value="' . (int)$d['id'] . '"><div class="row">' . field('Per payment', 'per', 'text', $d['per_txn_limit'], 'inputmode="decimal"') . field('Per day', 'daily', 'text', $d['daily_limit'], 'inputmode="decimal"') . select('Status', 'status', ['active' => 'Active', 'paused' => 'Paused'], $d['status']) . '</div>' . btn('Update', 'secondary sm') . '</form><div style="margin:10px 0">' . ($rh ?: '<span class="hint">No category or merchant restrictions.</span>') . '</div>' . form_start('res_add') . '<input type="hidden" name="id" value="' . (int)$d['id'] . '"><div class="row">' . select('Block', 'rtype', ['category' => 'Category', 'merchant' => 'Merchant name'], 'category') . field('Value', 'value', 'text', '', 'placeholder="gaming or Merchant name"') . '<div class="fixed field"><label>&nbsp;</label>' . btn('Add', 'secondary') . '</div></div></form>', '', 'flat'); }
$mineDep = row('SELECT d.*, u.name gname FROM dependents d JOIN users u ON u.id=d.guardian_id WHERE d.dependent_id=? LIMIT 1', [$uid]); $note = $mineDep ? '<div class="alert info">Your wallet has guardian controls: up to ' . e(money($mineDep['per_txn_limit'])) . ' per payment and ' . e(money($mineDep['daily_limit'])) . ' per day. Some categories or merchants may be blocked.</div>' : '';
echo $note . '<div class="grid g-main"><div class="grid">' . ($dh ?: card('Dependents', empty_state('You have no dependents.', 'users'))) . '</div>' . card('Add a dependent', form_start('dep_add') . field('Dependent account', 'who', 'text', '', 'required placeholder="email or phone"') . field('Max per payment (BDT)', 'per', 'text', '2000', 'required') . field('Max per day (BDT)', 'daily', 'text', '3000', 'required') . btn('Link dependent') . '</form><p class="hint">The dependent is notified. Limits apply to their BDT wallet.</p>') . '</div><div style="height:16px"></div>';
$ws = rows("SELECT w.id, u.name FROM wallets w JOIN users u ON u.id=w.user_id WHERE w.currency='BDT' AND (w.user_id=? OR w.user_id IN (SELECT dependent_id FROM dependents WHERE guardian_id=?))", [$uid, $uid]); $wopt = []; foreach ($ws as $w) $wopt[$w['id']] = $w['name'] . "'s BDT wallet";
$pols = rows('SELECT p.*, u.name FROM approval_policies p JOIN wallets w ON w.id=p.wallet_id JOIN users u ON u.id=w.user_id WHERE p.created_by=? OR w.user_id=?', [$uid, $uid]); $ph = '';
foreach ($pols as $p) { $ap = array_column(rows('SELECT u.name FROM approval_policy_approvers a JOIN users u ON u.id=a.user_id WHERE a.policy_id=?', [$p['id']]), 'name'); $ph .= '<div class="row" style="padding:8px 0;border-top:1px solid var(--line)"><div><strong>' . e($p['name']) . '</strong>: payments of ' . mny($p['min_amount']) . ' or more need <strong>' . (int)$p['required_approvals'] . '</strong> of ' . count($ap) . ' approvers<div class="hint">' . e(implode(', ', $ap)) . '</div></div>' . ((int)$p['created_by'] === $uid ? '<div class="fixed">' . form_start('pol_del', 'class="inline"') . '<input type="hidden" name="wallet" value="' . (int)$p['wallet_id'] . '">' . btn('Remove', 'secondary sm') . '</form></div>' : '') . '</div>'; }
$pend = rows("SELECT a.*, u.name req, w.user_id owner FROM approval_requests a JOIN users u ON u.id=a.requested_by JOIN wallets w ON w.id=a.wallet_id JOIN approval_policies p ON p.wallet_id=a.wallet_id JOIN approval_policy_approvers pa ON pa.policy_id=p.id AND pa.user_id=? WHERE a.status='pending' ORDER BY a.id", [$uid]); $pr = [];
foreach ($pend as $a) { $voted = val('SELECT decision FROM approval_votes WHERE request_id=? AND approver_id=?', [$a['id'], $uid]); $n = (int)val("SELECT COUNT(*) FROM approval_votes WHERE request_id=? AND decision='approve'", [$a['id']]); $pr[] = [e($a['req']), mny($a['amount']) . '<div class="hint">' . e($a['note']) . ' &middot; to ' . e(uname((int)val('SELECT user_id FROM wallets WHERE id=?', [$a['to_wallet_id']]))) . '</div>', $n . ' approval(s)', $voted ? badge($voted === 'approve' ? 'approved' : 'rejected') : form_start('vote', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$a['id'] . '"><input type="hidden" name="decision" value="approve">' . btn('Approve', 'sm') . '</form> ' . form_start('vote', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$a['id'] . '"><input type="hidden" name="decision" value="reject">' . btn('Reject', 'danger sm') . '</form>']; }
$mine = rows('SELECT a.* FROM approval_requests a WHERE a.requested_by=? ORDER BY a.id DESC LIMIT 6', [$uid]); $mr = []; foreach ($mine as $a) $mr[] = [e(fdate($a['created_at'])), mny($a['amount']), badge($a['status'])];
echo '<div class="grid g2"><div class="grid">' . card('Waiting for your decision', tbl(['Requested by', 'Payment', 'Progress', ''], $pr, 'Nothing needs your approval.')) . card('Your payments awaiting approval', tbl(['When', 'Amount', 'Status'], $mr, 'None.')) . '</div><div class="grid">' . card('Approval policies', ($ph ?: '<p class="muted">No policies yet.</p>') . '<hr>' . form_start('pol_set') . select('Wallet', 'wallet', $wopt) . '<div class="row">' . field('Needs approval from (BDT)', 'min', 'text', '5000', 'required inputmode="decimal"') . field('Approvals required', 'need', 'number', '2', 'min="1" max="5" required') . '</div>' . field('Approvers (emails, comma separated)', 'approvers', 'text', '', 'required') . btn('Save policy') . '</form>') . '</div></div>';
